1	import { test, expect, type Page } from "@playwright/test";
2	import * as fs from "node:fs/promises";
3	import * as path from "node:path";
4	
5	const LIVE_URL = "https://boldteq.com";
6	const LOCAL_URL = process.env.LOCAL_URL ?? "http://localhost:3000";
7	
8	const VIEWPORTS = [
9	  { name: "1440", width: 1440, height: 900 },
10	  { name: "1280", width: 1280, height: 800 },
11	  { name: "768", width: 768, height: 1024 },
12	  { name: "375", width: 375, height: 812 },
13	] as const;
14	
15	// Webflow root class → human label. Used to find each section on BOTH live and local.
16	// Local Next.js wraps these classes via CSS modules (hashed), so we also map a
17	// data-testid we add (later) — for now we query the Webflow class via partial
18	// `[class*="..."]` matching which works for both raw Webflow classes (live) and
19	// CSS-module-hashed classes (local) because Next.js preserves the original token
20	// inside the hash (`<token>__<hash>`).
21	const SECTIONS: Array<{ id: string; selector: string; label: string }> = [
22	  { id: "hero", selector: '[class*="section-high-judge"]', label: "Hero" },
23	  { id: "carousel", selector: '[class*="img-slider-sec"]', label: "Portfolio Carousel" },
24	  { id: "pain", selector: '[class*="slowing-sec"]', label: "Pain Points" },
25	  { id: "resolution", selector: '[class*="blue-card-sec"]', label: "Resolution Banner" },
26	  { id: "built-for", selector: '[class*="built-seccc"]', label: "Built For" },
27	  { id: "benefits", selector: '[class*="works-sec"], [class*="worksSec"]', label: "Benefits Grid" },
28	  { id: "how-it-works", selector: '[class*="makeit-sec"], [class*="sectionRegular3BlueSec"]', label: "How It Works" },
29	  { id: "pricing", selector: '[class*="new-price-sec"], [class*="newPriceSec"]', label: "Pricing" },
30	  { id: "comparison", selector: '[class*="ways-sec"], [class*="waysSec"]', label: "Comparison" },
31	  { id: "faq", selector: '[class*="home-faq"], [class*="faq-section"]', label: "FAQ" },
32	  { id: "footer", selector: "footer, [class*='footer']", label: "Footer" },
33	];
34	
35	const PROBE_PROPS = [
36	  "padding",
37	  "margin",
38	  "fontSize",
39	  "lineHeight",
40	  "fontWeight",
41	  "color",
42	  "backgroundColor",
43	  "borderRadius",
44	  "boxShadow",
45	  "gap",
46	  "gridTemplateColumns",
47	  "maxWidth",
48	  "width",
49	  "height",
50	  "display",
51	] as const;
52	
53	type Probe = {
54	  found: boolean;
55	  bbox: { x: number; y: number; width: number; height: number } | null;
56	  computed: Record<string, string> | null;
57	  childCount: number;
58	};
59	
60	async function probeSections(page: Page): Promise<Record<string, Probe>> {
61	  return await page.evaluate(
62	    ({ sections, props }) => {
63	      const out: Record<string, Probe> = {};
64	      for (const s of sections) {
65	        const el = document.querySelector(s.selector) as HTMLElement | null;
66	        if (!el) {
67	          out[s.id] = { found: false, bbox: null, computed: null, childCount: 0 };
68	          continue;
69	        }
70	        const r = el.getBoundingClientRect();
71	        const cs = window.getComputedStyle(el);
72	        const computed: Record<string, string> = {};
73	        for (const p of props) computed[p] = cs.getPropertyValue(p) || (cs as unknown as Record<string, string>)[p] || "";
74	        out[s.id] = {
75	          found: true,
76	          bbox: { x: r.x, y: r.y, width: r.width, height: r.height },
77	          computed,
78	          childCount: el.children.length,
79	        };
80	      }
81	      return out;
82	    },
83	    { sections: SECTIONS, props: PROBE_PROPS as unknown as string[] },
84	  );
85	}
86	
87	async function dismissOverlays(page: Page) {
88	  // Best-effort dismiss of cookie banners / chat widgets that interfere with
89	  // screenshot diffs. Failures are silently swallowed.
90	  await page
91	    .evaluate(() => {
92	      const sel = [
93	        "#chatwoot_live_chat_widget",
94	        "#chatwoot-widget-holder",
95	        ".onetrust-banner-sdk",
96	        '[id^="hs-eu-cookie-confirmation"]',
97	      ];
98	      for (const s of sel) {
99	        const el = document.querySelector(s) as HTMLElement | null;
100	        if (el) el.style.display = "none";
101	      }
102	    })
103	    .catch(() => {});
104	}
105	
106	async function captureForViewport(
107	  page: Page,
108	  url: string,
109	  scope: "live" | "local",
110	  vp: typeof VIEWPORTS[number],
111	) {
112	  await page.setViewportSize({ width: vp.width, height: vp.height });
113	  await page.goto(url, { waitUntil: "networkidle", timeout: 60_000 }).catch(async () => {
114	    await page.goto(url, { waitUntil: "domcontentloaded", timeout: 60_000 });
115	  });
116	  await page.waitForTimeout(2_000);
117	  await dismissOverlays(page);
118	  await page.evaluate(() => window.scrollTo(0, 0));
119	  await page.waitForTimeout(500);
120	
121	  const screenshotDir = path.join("tests", "screenshots", "baseline", scope);
122	  await fs.mkdir(screenshotDir, { recursive: true });
123	  const screenshotPath = path.join(screenshotDir, `${vp.name}.png`);
124	  await page.screenshot({ path: screenshotPath, fullPage: true, animations: "disabled" });
125	
126	  const probes = await probeSections(page);
127	  return { viewport: vp.name, screenshotPath, probes };
128	}
129	
130	function diffComputed(live: Probe, local: Probe) {
131	  const out: Record<string, { live: string; local: string }> = {};
132	  if (!live.found || !local.found) return out;
133	  if (!live.computed || !local.computed) return out;
134	  for (const k of Object.keys(live.computed)) {
135	    const a = live.computed[k];
136	    const b = local.computed[k];
137	    if (a !== b) out[k] = { live: a, local: b };
138	  }
139	  return out;
140	}
141	
142	test.describe("Homepage pixel-perfect audit", () => {
143	  test("capture baselines + diff report", async ({ browser }) => {
144	    test.setTimeout(600_000);
145	
146	    const liveCtx = await browser.newContext();
147	    const localCtx = await browser.newContext();
148	    const livePage = await liveCtx.newPage();
149	    const localPage = await localCtx.newPage();
150	
151	    type Snapshot = Awaited<ReturnType<typeof captureForViewport>>;
152	    const live: Record<string, Snapshot> = {};
153	    const local: Record<string, Snapshot> = {};
154	
155	    for (const vp of VIEWPORTS) {
156	      console.log(`▶ viewport ${vp.name} — live`);
157	      live[vp.name] = await captureForViewport(livePage, LIVE_URL, "live", vp);
158	      console.log(`▶ viewport ${vp.name} — local`);
159	      local[vp.name] = await captureForViewport(localPage, LOCAL_URL, "local", vp);
160	    }
161	
162	    type SectionDiff = {
163	      id: string;
164	      label: string;
165	      liveFound: boolean;
166	      localFound: boolean;
167	      bboxDelta: { dx: number; dy: number; dw: number; dh: number } | null;
168	      computedDiff: Record<string, { live: string; local: string }>;
169	    };
170	    const report: Array<{ viewport: string; sections: SectionDiff[] }> = [];
171	
172	    for (const vp of VIEWPORTS) {
173	      const sections: SectionDiff[] = [];
174	      for (const s of SECTIONS) {
175	        const lp = live[vp.name].probes[s.id];
176	        const cp = local[vp.name].probes[s.id];
177	        sections.push({
178	          id: s.id,
179	          label: s.label,
180	          liveFound: lp.found,
181	          localFound: cp.found,
182	          bboxDelta:
183	            lp.bbox && cp.bbox
184	              ? {
185	                  dx: Math.round((cp.bbox.x - lp.bbox.x) * 10) / 10,
186	                  dy: Math.round((cp.bbox.y - lp.bbox.y) * 10) / 10,
187	                  dw: Math.round((cp.bbox.width - lp.bbox.width) * 10) / 10,
188	                  dh: Math.round((cp.bbox.height - lp.bbox.height) * 10) / 10,
189	                }
190	              : null,
191	          computedDiff: diffComputed(lp, cp),
192	        });
193	      }
194	      report.push({ viewport: vp.name, sections });
195	    }
196	
197	    const reportPath = path.join("tests", "screenshots", "diff-report.json");
198	    await fs.writeFile(reportPath, JSON.stringify(report, null, 2), "utf8");
199	
200	    // Human-readable summary log
201	    console.log("\n=== HOMEPAGE DIFF SUMMARY ===");
202	    for (const vpReport of report) {
203	      console.log(`\n▶ Viewport ${vpReport.viewport}px`);
204	      for (const s of vpReport.sections) {
205	        const status = !s.liveFound
206	          ? "MISSING-LIVE"
207	          : !s.localFound
208	            ? "MISSING-LOCAL"
209	            : Object.keys(s.computedDiff).length === 0 &&
210	                s.bboxDelta &&
211	                Math.abs(s.bboxDelta.dh) < 4
212	              ? "OK"
213	              : "DRIFT";
214	        const propCount = Object.keys(s.computedDiff).length;
215	        const dh = s.bboxDelta?.dh ?? "n/a";
216	        console.log(`  [${status}] ${s.label.padEnd(22)} dh=${dh} computedDiff=${propCount}`);
217	      }
218	    }
219	
220	    // Don't fail test on drift — this is an audit run.
221	    expect(report.length).toBeGreaterThan(0);
222	  });
223	});
